# figures/style.py — the paper's design system (generated by the paper-figures skill).
# Target path in a paper repo: <repo>/figures/style.py
#
# Palette-role discipline, grayscale-parallel encodings and the exact-size export
# pattern follow practice extracted from Amir Rafe's public paper repositories
# (MIT-licensed); see the skill's references/attribution.md. [E] rules are evidence,
# [R] rules are this skill's requirements — [R] wins.
"""Design system: Okabe-Ito role palette, venue profiles, exact-size export.

Figure scripts import this as ``S`` and use only ``S.*`` — never raw hex,
``plt.rcParams`` or ``bbox_inches``. Public API:

  C, AMBER_INK, MARKERS, LINESTYLES, HATCHES       encodings (one role per meaning)
  FULL, COL, DPI                                   set by apply()/apply_from_config()
  tint(hex, frac), seq_cmap(role), div_cmap()      colour derivation (never new hues)
  apply(venue, stage), apply_from_config()         rcParams per venue profile
  save(fig, name, mode="exact")                    PDF + PNG + gray proof + sidecar
  panel_title, panel_label, light_grid, despine,
  finish(fig), tex_color_defs()                    helpers
"""
from __future__ import annotations

import hashlib
import json
import warnings
from pathlib import Path

import matplotlib as mpl
import matplotlib.pyplot as plt
from matplotlib.colors import LinearSegmentedColormap, to_rgb
from matplotlib.transforms import Bbox

# --------------------------------------------------------------------------- palette
# Okabe-Ito with fixed roles, plus structure colours. One role per meaning for
# the whole paper [R]; record the role→meaning mapping in paper_config.yaml.
C = {
    "obs": "#0072B2",      # blue   — observed / primary series
    "adj": "#E69F00",      # amber  — adjusted / secondary
    "exp": "#009E73",      # green  — expected / model
    "alert": "#D55E00",    # vermilion — flagged / out-of-range
    "aux": "#CC79A7",      # purple — auxiliary series
    "light": "#56B4E9",    # sky    — light variant series
    "neutral": "#7F7F7F",  # grey   — reference / all-else
    "ink": "#222222",      # text and axis ink
    "muted": "#5A6066",    # secondary text
    "rule": "#D9E1E5",     # grid / rules
    "band": "#EEF1F2",     # background bands
}
AMBER_INK = "#B07D14"  # amber is unreadable as type; use this for amber text

# Parallel encodings so series stay distinct in grayscale [E].
_ROLES = ["obs", "adj", "exp", "alert", "aux", "light", "neutral"]
MARKERS = {"obs": "o", "adj": "s", "exp": "^", "alert": "D",
           "aux": "v", "light": "P", "neutral": "X"}
LINESTYLES = {"obs": "-", "adj": "--", "exp": "-.", "alert": ":",
              "aux": (0, (3, 1, 1, 1)), "light": (0, (5, 2)),
              "neutral": (0, (1, 1))}
HATCHES = {"obs": "", "adj": "//", "exp": "..", "alert": "xx",
           "aux": "\\\\", "light": "++", "neutral": "--"}


def tint(hex_color: str, frac: float) -> tuple:
    """Lighten a palette colour toward white by ``frac`` in [0, 1] — never a new hue."""
    r, g, b = to_rgb(hex_color)
    return (r + (1 - r) * frac, g + (1 - g) * frac, b + (1 - b) * frac)


def seq_cmap(role: str = "obs") -> LinearSegmentedColormap:
    """Sequential ramp: white → the role colour."""
    return LinearSegmentedColormap.from_list(f"seq_{role}", ["#FFFFFF", C[role]])


def div_cmap() -> LinearSegmentedColormap:
    """Diverging ramp: grey → white → amber."""
    return LinearSegmentedColormap.from_list(
        "div_grey_amber", [C["neutral"], "#FFFFFF", C["adj"]])


# ------------------------------------------------------------------- venue profiles
# [R] Verify each against its source when the paper is close to submission —
# journal specs change. Widths in inches; font sizes in points.
#   text_min/text_max : regular text (axis titles, legend, annotations); max=None → no ceiling
#   tick_min          : floor for tick numerals / footnote-grade text
#   panel_pt          : panel-label exception (e.g. Nature 8 pt bold lowercase)
ABS_FLOOR_PT = 5.0  # nothing on any figure is ever below 5 pt [R]

PROFILES = {
    "nature": dict(
        full_in=7.20, col_in=3.50,                      # 183 mm / 89 mm
        text_min=5.0, text_max=7.0, tick_min=5.0,       # 5–7 pt, max 7 is binding
        base_pt=6.0, tick_pt=5.5, panel_pt=8.0,         # panel labels 8 pt bold lowercase
        panel_style="bold-lower", family="sans", dpi=600, placement="tbp",
        source="https://www.nature.com/nature/for-authors/formatting-guide",
        checked="2026-10-12"),
    "acmsmall": dict(
        full_in=395.8225 / 72.27, col_in=None,          # \textwidth of acmart(acmsmall)
        text_min=7.5, text_max=None, tick_min=7.5,      # everything (math scripts too) ≥ 7.5
        base_pt=8.0, tick_pt=7.5, panel_pt=8.0,
        panel_style="paren", family="serif", dpi=300, placement="tbp",
        # For final ACM production, matching the document font (Libertine) needs the
        # pgf backend; the default here keeps a portable serif and embeds it.
        source="https://www.acm.org/publications/proceedings-template",
        checked="2026-10-12"),
    "elsevier": dict(
        full_in=7.48, col_in=3.54,                      # 190 mm / 90 mm
        text_min=7.0, text_max=10.0, tick_min=6.0,
        base_pt=8.0, tick_pt=7.0, panel_pt=8.0,
        panel_style="paren", family="serif", dpi=300, placement="tbp",
        source="https://www.elsevier.com/about/policies-and-standards/author/artwork-and-media-instructions",
        checked="2026-10-12"),
    "trb": dict(
        full_in=6.5, col_in=None,                       # TRR/TRB single-column 6.5 in
        text_min=8.0, text_max=None, tick_min=7.0,
        base_pt=8.0, tick_pt=7.0, panel_pt=8.0,
        panel_style="paren", family="sans", dpi=300, placement="H",
        source="https://www.trb.org/Publications/PubsTRRJournalAuthors.aspx",
        checked="2026-10-12"),
    "ieee": dict(
        full_in=7.16, col_in=3.5,
        text_min=8.0, text_max=10.0, tick_min=7.0,
        base_pt=8.0, tick_pt=7.0, panel_pt=8.0,
        panel_style="paren", family="serif", dpi=300, placement="tbp",
        source="https://journals.ieeeauthorcenter.ieee.org/create-your-ieee-journal-article/create-graphics-for-your-article/",
        checked="2026-10-12"),
    "generic": dict(
        full_in=6.5, col_in=3.25,
        text_min=7.0, text_max=9.0, tick_min=6.0,
        base_pt=8.0, tick_pt=7.0, panel_pt=8.0,
        panel_style="paren", family="sans", dpi=300, placement="tbp",
        source="(no named venue — generic US-letter manuscript)",
        checked="2026-10-12"),
}

# Module state set by apply(); figure scripts read FULL/COL/DPI only.
FULL: float = PROFILES["generic"]["full_in"]
COL: float = PROFILES["generic"]["col_in"]
DPI: int = PROFILES["generic"]["dpi"]
_STATE = {"venue": "generic", "stage": "final", "applied": False}


def repo_root() -> Path:
    """The paper repo root (style.py lives in <repo>/figures/)."""
    return Path(__file__).resolve().parent.parent


def read_config(path: Path | None = None) -> dict:
    """Minimal paper_config.yaml reader (top-level scalar keys only; no pyyaml)."""
    path = path or (repo_root() / "paper_config.yaml")
    cfg: dict = {}
    if not path.exists():
        return cfg
    for raw in path.read_text(encoding="utf-8").splitlines():
        line = raw.split("#", 1)[0].rstrip()
        if not line or line.startswith((" ", "\t")) or ":" not in line:
            continue
        key, _, val = line.partition(":")
        cfg[key.strip()] = val.strip()
    return cfg


def apply(venue: str = "generic", stage: str = "final") -> dict:
    """Set rcParams for a venue profile [E→R]. Returns the profile dict."""
    if venue not in PROFILES:
        raise KeyError(f"unknown venue {venue!r}; known: {sorted(PROFILES)}")
    if stage not in ("submission", "final"):
        raise ValueError("stage must be 'submission' or 'final'")
    global FULL, COL, DPI
    p = PROFILES[venue]
    _STATE.update(venue=venue, stage=stage, applied=True)
    FULL = p["full_in"]
    COL = p["col_in"] if p["col_in"] else round(p["full_in"] / 2, 3)
    DPI = p["dpi"]
    sans = p["family"] == "sans"
    mpl.rcParams.update({
        # canvas and spines
        "figure.facecolor": "white", "axes.facecolor": "white",
        "savefig.facecolor": "white",
        "axes.spines.top": False, "axes.spines.right": False,
        "axes.linewidth": 0.5, "axes.edgecolor": C["ink"],
        "xtick.major.width": 0.5, "ytick.major.width": 0.5,
        "xtick.minor.width": 0.4, "ytick.minor.width": 0.4,
        "xtick.major.size": 2.5, "ytick.major.size": 2.5,
        # ink
        "text.color": C["ink"], "axes.labelcolor": C["ink"],
        "xtick.color": C["ink"], "ytick.color": C["ink"],
        # grid: off by default; light_grid() turns on a faint one
        "axes.grid": False, "grid.color": C["rule"], "grid.linewidth": 0.5,
        "axes.axisbelow": True,
        # legend: frameless
        "legend.frameon": False, "legend.handlelength": 1.6,
        "legend.borderaxespad": 0.2,
        # fonts: embed TrueType (fonttype 42), sizes per profile
        "pdf.fonttype": 42, "ps.fonttype": 42, "svg.fonttype": "none",
        "font.family": "sans-serif" if sans else "serif",
        "font.sans-serif": ["Arial", "Helvetica", "DejaVu Sans"],
        "font.serif": ["Times New Roman", "Times", "Nimbus Roman", "DejaVu Serif"],
        "mathtext.fontset": "dejavusans" if sans else "dejavuserif",
        "font.size": p["base_pt"],
        "axes.labelsize": p["base_pt"], "axes.titlesize": p["base_pt"],
        "xtick.labelsize": p["tick_pt"], "ytick.labelsize": p["tick_pt"],
        "legend.fontsize": p["base_pt"], "figure.titlesize": p["base_pt"],
        # geometry: constrained layout fits all labels INSIDE the declared
        # figsize, which exact mode exports as the page — nothing gets clipped
        # and nothing relies on bbox_inches="tight".
        "figure.constrained_layout.use": True,
        "figure.constrained_layout.h_pad": 0.03,
        "figure.constrained_layout.w_pad": 0.03,
        "figure.dpi": 110, "savefig.dpi": p["dpi"],
        "lines.linewidth": 1.2, "lines.markersize": 4.0,
        "errorbar.capsize": 0.0,
        "axes.unicode_minus": True,
    })
    return p


def apply_from_config() -> dict:
    """apply() using venue/stage from the repo's paper_config.yaml."""
    cfg = read_config()
    return apply(cfg.get("venue", "generic"), cfg.get("stage", "final"))


# ----------------------------------------------------------------------- text audit
def _add_text(items: list, t, kind: str) -> None:
    s = t.get_text()
    if not s or not s.strip():
        return
    if t.get_gid() == "panel_label":
        kind = "panel_label"
    items.append({"pt": float(t.get_fontsize()), "kind": kind, "s": s})


def _collect_texts(fig) -> list:
    """Every visible Text object with its element kind, for the sidecar."""
    items: list = []
    for ax in fig.get_axes():
        _add_text(items, ax.xaxis.label, "label")
        _add_text(items, ax.yaxis.label, "label")
        _add_text(items, ax.title, "label")
        for t in (ax.get_xticklabels() + ax.get_yticklabels()
                  + ax.get_xticklabels(minor=True) + ax.get_yticklabels(minor=True)):
            _add_text(items, t, "tick")
        leg = ax.get_legend()
        if leg is not None:
            for t in leg.get_texts():
                _add_text(items, t, "legend")
        for t in ax.texts:
            _add_text(items, t, "annotation")
    for t in fig.texts:
        _add_text(items, t, "annotation")
    for leg in fig.legends:
        for t in leg.get_texts():
            _add_text(items, t, "legend")
    return items


def _sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


# ---------------------------------------------------------------------------- save
def save(fig, name: str, mode: str = "exact", outdir: str | Path | None = None) -> Path:
    """Export PDF + PNG + gray/PNG + sidecar. The two modes are never mixed [R].

    exact (default): page is exactly the declared figsize — for LaTeX at scale 1.
    tight: previews/slides only; exempt from the width gate, never included.
    """
    if mode not in ("exact", "tight"):
        raise ValueError("mode must be 'exact' or 'tight'")
    if not _STATE["applied"]:
        raise RuntimeError("call S.apply(venue, stage) before S.save()")
    p = PROFILES[_STATE["venue"]]
    out = Path(outdir) if outdir else Path(__file__).resolve().parent / "out"
    (out / "gray").mkdir(parents=True, exist_ok=True)

    w, h = (float(x) for x in fig.get_size_inches())
    if mode == "exact" and not (abs(w - FULL) < 0.01 or abs(w - COL) < 0.01):
        warnings.warn(
            f"{name}: width {w:.3f} in is neither FULL ({FULL:.3f}) nor COL "
            f"({COL:.3f}); check_figures will fail this figure.", stacklevel=2)

    if mode == "exact":
        # Explicit page == figsize; never bbox_inches="tight" in exact mode [R].
        kw = dict(bbox_inches=Bbox.from_bounds(0, 0, w, h), pad_inches=0)
    else:
        kw = dict(bbox_inches="tight", pad_inches=0.02)

    pdf = out / f"{name}.pdf"
    png = out / f"{name}.png"
    fig.savefig(pdf, **kw)
    fig.savefig(png, dpi=p["dpi"], **kw)

    # Grayscale proof — always produced [R].
    from PIL import Image
    Image.open(png).convert("L").save(out / "gray" / f"{name}.png")

    # Sidecar captured at save time (the only moment the Text objects exist).
    cfg = repo_root() / "paper_config.yaml"
    meta = {
        "target_w_in": round(w, 4),
        "target_h_in": round(h, 4),
        "mode": mode,
        "venue": _STATE["venue"],
        "stage": _STATE["stage"],
        "config_sha256": _sha256(cfg) if cfg.exists() else None,
        "pdf_sha256": _sha256(pdf),
        "texts": _collect_texts(fig),
    }
    (out / f"{name}.meta.json").write_text(json.dumps(meta, indent=1), encoding="utf-8")
    return pdf


# ------------------------------------------------------------------------- helpers
def panel_title(ax, letter: str, title: str) -> None:
    """'(a) Title', left-aligned, at the profile's regular text size [E]."""
    ax.set_title(f"({letter}) {title}", loc="left", pad=4)


def panel_label(ax, letter: str) -> None:
    """Nature-style panel label: bold lowercase letter, profile panel_pt [E]."""
    p = PROFILES[_STATE["venue"]]
    t = ax.text(-0.02, 1.02, letter.lower(), transform=ax.transAxes,
                fontsize=p["panel_pt"], fontweight="bold",
                ha="right", va="bottom", color=C["ink"])
    t.set_gid("panel_label")


def light_grid(ax, axis: str = "y") -> None:
    """Faint grid at most [E]: thin rules behind the data."""
    ax.grid(True, axis=axis, color=C["rule"], linewidth=0.5)
    ax.set_axisbelow(True)


def despine(ax, left: bool = False, bottom: bool = False) -> None:
    """Top/right are already off; optionally drop left/bottom too."""
    ax.spines["top"].set_visible(False)
    ax.spines["right"].set_visible(False)
    if left:
        ax.spines["left"].set_visible(False)
        ax.tick_params(left=False)
    if bottom:
        ax.spines["bottom"].set_visible(False)
        ax.tick_params(bottom=False)


def finish(fig) -> None:
    """Sentence-case axis labels and align them across panels [E]."""
    for ax in fig.get_axes():
        for get, set_ in ((ax.get_xlabel, ax.set_xlabel),
                          (ax.get_ylabel, ax.set_ylabel)):
            s = get()
            if s and s[0].islower():
                set_(s[0].upper() + s[1:])
    fig.align_labels()


def tex_color_defs() -> str:
    r"""\definecolor lines so the manuscript can reference palette swatches."""
    lines = [f"\\definecolor{{{k}}}{{HTML}}{{{v.lstrip('#')}}}"
             for k, v in C.items()]
    lines.append(f"\\definecolor{{amberink}}{{HTML}}{{{AMBER_INK.lstrip('#')}}}")
    return "\n".join(lines)
